const money=n=>'RM'+n.toLocaleString('en-MY',{minimumFractionDigits:Number.isInteger(n)?0:2,maximumFractionDigits:2});
let cart={};try{const saved=JSON.parse(localStorage.getItem('eskem-cart')||'{}');for(const [id,q] of Object.entries(saved)){if(products[id]&&Number.isInteger(q)&&q>0&&q<=99)cart[id]=q;}}catch{}
let filter='all',expanded=false;
const card=(p,id)=>`<article class="product"><button class="product-photo" data-product="${id}" aria-label="View ${p.name}"><img src="${assets+p.image}" alt="${p.name}" loading="lazy" width="500" height="500">${p.alternate?`<img class="alternate" src="${assets+p.alternate}" alt="" loading="lazy" width="500" height="500">`:''}</button><h3><button data-product="${id}">${p.name}</button></h3><p class="price">${money(p.price)}</p><button class="quick-add" data-add="${id}" aria-label="Quick add ${p.name}">+ Quick add</button></article>`;
function renderProducts(){const list=products.map((p,id)=>({p,id})).filter(({p})=>filter==='all'||(filter==='seasonal'?p.seasonal:p.type===filter));$('#products').innerHTML=list.map(({p,id})=>card(p,id)).join('');$('#products').classList.toggle('expanded',expanded);$('#filters').hidden=!expanded;document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));$('.shop-all').hidden=expanded;$('.arrows').hidden=expanded;$('#shop-title').textContent=({all:'Ice Cream for Everyone',pints:'Shop Ice Cream',cakes:'Ice Cream Cakes',seasonal:'Deepavali Delights'})[filter];}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function openDialog(id){closeDialogs();$('#'+id).showModal();if(id==='search'){search();$('#search-input').focus();}if(id==='cart')renderCart();}
function persistCart(){try{localStorage.setItem('eskem-cart',JSON.stringify(cart));}catch{}renderCart();}
function renderCart(){const entries=Object.entries(cart);const count=entries.reduce((n,[,q])=>n+q,0);const total=entries.reduce((n,[id,q])=>n+products[id].price*q,0);$('#cart-count').textContent=count;$('#cart-count').hidden=!count;$('#cart-total-items').textContent=count?`(${count})`:'';$('.cart-toggle').setAttribute('aria-label',`Open cart, ${count} items`);if(!count){$('#cart-content').innerHTML='<div class="cart-empty"><span style="font-size:55px">♧</span><h3>Your cart is waiting for happiness</h3><p>Add your favourite ice cream or a celebration cake.</p><button class="pill dark" data-filter="all">Explore flavours</button></div>';return;}$('#cart-content').innerHTML=`<div class="shipping-note">${total>=180?'You have reached the free delivery minimum!':`You’re ${money(180-total)} away from free delivery.`}<div class="shipping-bar"><span style="width:${Math.min(100,total/180*100)}%"></span></div></div>${entries.map(([id,q])=>{const p=products[id];return `<div class="cart-line"><button data-product="${id}" aria-label="View ${p.name}"><img src="${assets+p.image}" alt="${p.name}"></button><div><h3>${p.name}</h3><p>${money(p.price*q)}</p><div class="quantity"><button data-change="${id}" data-delta="-1" aria-label="Decrease ${p.name}">−</button><span>${q}</span><button data-change="${id}" data-delta="1" aria-label="Increase ${p.name}" ${q>=99?'disabled':''}>+</button></div><button class="remove" data-remove="${id}" aria-label="Remove ${p.name}">Remove</button></div></div>`;}).join('')}<div class="cart-summary"><p><span>Subtotal</span><span id="cart-subtotal">${money(total)}</span></p><div class="cart-note">Delivery calculated at checkout.</div><button class="pill dark" data-info="checkout">Review order</button><div class="cart-note">Demo storefront · No payment is collected.</div></div>`;}
function add(id,q=1){cart[id]=Math.min(99,(cart[id]||0)+q);persistCart();openDialog('cart');}
function productDetail(id){const p=products[id];if(!p)return;$('#product-detail').innerHTML=`<img src="${assets+p.image}" alt="${p.name}"><div class="detail-copy"><p>${p.seasonal?'DEEPAVALI DELIGHTS':p.type==='cakes'?'SCOOPS OF CELEBRATION':'HAPPINESS BY THE PINT'}</p><h2 id="product-name">${p.name}</h2><p class="detail-price">${money(p.price)}</p><p>${p.description}</p><p class="cart-note">Product preview. Check the original shop for current ingredients, allergens and availability.</p><div class="quantity"><button id="detail-minus" aria-label="Decrease quantity">−</button><span id="detail-quantity">1</span><button id="detail-plus" aria-label="Increase quantity">+</button></div><button class="pill dark" id="detail-add">Add to cart · ${money(p.price)}</button></div>`;let q=1;const update=()=>{$('#detail-quantity').textContent=q;$('#detail-add').textContent='Add to cart · '+money(p.price*q);};$('#detail-minus').onclick=()=>{q=Math.max(1,q-1);update();};$('#detail-plus').onclick=()=>{q=Math.min(99,q+1);update();};$('#detail-add').onclick=()=>add(id,q);openDialog('product-dialog');}
function search(){const query=$('#search-input').value.trim().toLowerCase();const hits=products.map((p,id)=>({p,id})).filter(({p})=>!query||p.name.toLowerCase().includes(query));$('#search-results').innerHTML=hits.length?hits.map(({p,id})=>`<button class="search-result" data-product="${id}"><img src="${assets+p.image}" alt=""><span>${p.name}</span><strong>${money(p.price)}</strong></button>`).join(''):'<p>No scoops found. Try “chocolate”, “cake” or “mango”.</p>';}
const info={
 story:['Our story','<p>Inside Scoop started in 2013 with Edmund and Shiew Li, who spent endless hours testing and churning flavours. Their first shop opened in Bangsar with 16 flavours, including Durian and Valrhona Chocolate.</p><p>From those first scoops to shops across Malaysia, it is a story built around sharing a little happiness.</p><a class="pill dark" href="https://insidescoop.com.my/pages/about" target="_blank" rel="noopener">Read the full story ↗</a>'],
 club:['Welcome to the Insiders Club','<p>Explore membership, points and rewards on the official Insiders Club website.</p><a class="pill dark" href="https://insider.insidescoop.com.my/" target="_blank" rel="noopener">Visit Insiders Club ↗</a>'],
 monday:['Scoop away the Monday blues','<p>Explore the RM7 Single Scoop offer and its current terms on the original Inside Scoop website.</p><a class="pill dark" href="https://insidescoop.com.my/pages/scoop-away-the-monday-blues" target="_blank" rel="noopener">View the offer ↗</a>'],
 gift:['Give a little happiness','<p>Share a scoop with someone special. e-Gifts are available through the official Inside Scoop shop.</p><a class="pill dark" href="https://insidescoop.com.my/collections/e-gift" target="_blank" rel="noopener">Explore e-Gifts ↗</a>'],
 events:['Make it a scoop-worthy celebration','<p>Bring ice cream to your next party or event. Browse event options and contact the Inside Scoop team on their official website.</p><a class="pill dark" href="https://insidescoop.com.my/pages/contact-us" target="_blank" rel="noopener">Enquire about an event ↗</a>'],
 account:['Your account','<p>This recreation does not collect passwords or create customer accounts. Your demo cart is saved in this browser.</p><a class="pill dark" href="https://insidescoop.com.my/account" target="_blank" rel="noopener">Open official account page ↗</a>'],
 faq:['Frequently asked questions','<p><strong>Can I order here?</strong><br>This is a storefront demonstration. You can explore products and try the cart, but purchases are not processed.</p><p><strong>Where can I find delivery and ingredient details?</strong><br>Visit the original shop for current availability, delivery areas, ingredients and allergens.</p><a href="https://insidescoop.com.my/pages/faqs" target="_blank" rel="noopener">Read official FAQs ↗</a>'],
 terms:['Preview terms','<p>This Eskem project recreates the supplied Inside Scoop reference for demonstration. Product images, branding, prices and promotional content are from the reference snapshot. Orders, stock checks and payments are not connected.</p>'],
 privacy:['Your privacy','<p>Your demo cart and newsletter preference are stored only in this browser. This website does not send your email address, collect payments, or create an account. External links open the original services, which have their own privacy policies.</p>'],
 contact:['Say hello','<p>For real orders, store information or event enquiries, contact Inside Scoop through its official website.</p><a class="pill dark" href="https://insidescoop.com.my/pages/contact-us" target="_blank" rel="noopener">Contact Inside Scoop ↗</a>']
};
function showInfo(key){let value=info[key];if(key==='checkout'){const total=Object.entries(cart).reduce((sum,[id,q])=>sum+products[id].price*q,0);value=['Your order preview',`<p>${Object.entries(cart).map(([id,q])=>`${q} × ${products[id].name}`).join('<br>')}</p><p><strong>Total: ${money(total)}</strong></p><p>This is a demo order summary. No order has been placed and no payment has been taken.</p><button class="pill dark" data-open="cart">Back to cart</button>`];}if(!value)return;$('#info-title').textContent=value[0];$('#info-content').innerHTML=value[1];openDialog('info');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('.close'))b.closest('dialog').close();if(b.dataset.open)openDialog(b.dataset.open);if(b.dataset.filter){filter=b.dataset.filter;expanded=true;closeDialogs();renderProducts();$('#shop').scrollIntoView({behavior:'smooth'});}if(b.dataset.product!==undefined)productDetail(Number(b.dataset.product));if(b.dataset.add!==undefined)add(Number(b.dataset.add));if(b.dataset.change!==undefined){const id=b.dataset.change;cart[id]=Math.min(99,(cart[id]||0)+Number(b.dataset.delta));if(cart[id]<=0)delete cart[id];persistCart();}if(b.dataset.remove!==undefined){delete cart[b.dataset.remove];persistCart();}if(b.dataset.info)showInfo(b.dataset.info);if(b.matches('.nav-link')){const parent=b.closest('.dropdown');const open=parent.classList.toggle('open');b.setAttribute('aria-expanded',String(open));}if(b.closest('#menu')&&b.tagName==='A')closeDialogs();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.dropdown.open').forEach(d=>{d.classList.remove('open');d.querySelector('button').setAttribute('aria-expanded','false');});});
$('#search-input').addEventListener('input',search);
$('#products-prev').onclick=()=>$('#products').scrollBy({left:-$('#products').clientWidth,behavior:'smooth'});
$('#products-next').onclick=()=>$('#products').scrollBy({left:$('#products').clientWidth,behavior:'smooth'});
const slides=[
 ['Deepavali_2026_TV3_Banners_OS_Banner_for_desktop.jpg','Deepavali_2026_TV3_Banners_OS_banner_for_mobile.jpg','Deepavali Delights — egg-free Gulab Jamun cake and Matka Pot Set. Shop now.','seasonal'],
 ['RM7_Mondays_Desktop_2d38d926-6f5f-42ca-b8fd-bba4274fe827.jpg','RM7_Mondays_Mobile_5d65bb29-99a0-40ee-8f73-3a029de3ed6b.jpg','Scoop away the Monday blues — RM7 Mondays.','monday'],
 ['Pint_OS_Banner_2026_OS_Banner_Desktop.jpg','Pint_OS_Banner_2026_OS_Banner_Mobile.jpg','Your favourite Inside Scoop ice cream pints.','pints'],
 ['Cake_Compilation_2026_OS_App_Banner2_OS_Banner.jpg','Cake_Compilation_2026_OS_App_Banner2_OS_Banner_Mobile.jpg','Celebrate with Inside Scoop ice cream cakes.','cakes']
];
let slide=0;function showSlide(n){slide=(n+slides.length)%slides.length;const [desktop,mobile,alt]=slides[slide];$('#hero-image').src=assets+desktop;$('#hero-image').alt=alt;$('#hero-mobile').srcset=assets+mobile;$('#slide-status').textContent=`Offer ${slide+1} of ${slides.length}`;}
$('#next-slide').onclick=()=>showSlide(slide+1);$('#previous-slide').onclick=()=>showSlide(slide-1);
$('#hero-link').onclick=e=>{e.preventDefault();const target=slides[slide][3];if(target==='monday'){showInfo('monday');return;}filter=target;expanded=true;renderProducts();$('#shop').scrollIntoView({behavior:'smooth'});};
$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();try{localStorage.setItem('eskem-newsletter-demo','saved');}catch{}$('#newsletter-status').textContent='Thanks! Demo preference saved on this device. No email has been sent or subscribed.';$('#newsletter-form').reset();});
renderProducts();renderCart();
